static string WriteBlob(string root, byte[] content)
{
    var header = Encoding.ASCII.GetBytes($"blob {content.Length}\0");
    var full = header.Concat(content).ToArray();
    var id = Convert.ToHexString(SHA1.HashData(full)).ToLowerInvariant();
    var path = Path.Combine(root, ".mygit", "objects", id[..2], id[2..]);
    Directory.CreateDirectory(Path.GetDirectoryName(path)!);
    using var file = File.Create(path);
    using var zlib = new ZLibStream(file, CompressionLevel.Optimal);
    zlib.Write(full);
    return id;
}
